import numpy as np
def solve(data):
    first = np.random.default_rng(data["seed"]).integers(1, 7, size=data["n"])
    second = np.random.default_rng(data["seed"]).integers(1, 7, size=data["n"])
    return {"count": first.size, "same": np.array_equal(first, second)}
